namespace Blueprint.HttpClient.Tests;

/// <summary>
/// A typed client over operations declared in this assembly, as a consumer's typed client lives beside its contract's
/// operations. Their request builders are generated by the same build as the client, so the client generator cannot see
/// them and decides from each operation's declaration that they will exist.
/// </summary>
/// <remarks>
/// Internal, so the generated half of the class must agree with the hand-written half's accessibility.
/// </remarks>
[BlueprintClient]
[BlueprintClientInclude(typeof(CopyTemplateCommand))]
[BlueprintClientInclude(typeof(FindTemplateCopiesQuery))]
internal partial class LocalOperationsApi
{
    /// <summary>
    /// Gets the transport every call is sent with, which a registration test reads the JSON options of.
    /// </summary>
    public BlueprintHttpClient Transport => this._client;
}
